cd /workspace/tmp && ffmpeg -v info -i /workspace/output/repurpose.mp4 -af "astats=metadata=1:reset=1,ametadata=print:key=lavfi.astats.Overall.RMS_level:file=astats.txt" -t 74.76 -f null - 2>/dev/null; python3 - <<'EOF'
import re
v = [float(x) for x in re.findall(r'RMS_level=(-?[\d.]+|inf)', open('/workspace/tmp/astats.txt').read()) if x not in ('inf','-inf')]
if v: print(f"samples: {len(v)}  min: {min(v):.1f} dB  max: {max(v):.1f} dB  mean: {sum(v)/len(v):.1f} dB")
else: print("no rms values")
EOF

